using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using Demo5.FrontEnd;
public static class BuildFacilityContours {
 static Vector2[] Points(params float[] xy){return Enumerable.Range(0,xy.Length/2).Select(i=>new Vector2(xy[i*2],xy[i*2+1])).ToArray();}
 static void Set(Button b,Material mat,Text help,string name,params Vector2[][] paths){var all=paths.SelectMany(p=>p).ToArray();float x=all.Min(p=>p.x),y=all.Min(p=>p.y);var r=(RectTransform)b.transform;r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(all.Max(p=>p.x)-x,all.Max(p=>p.y)-y);var f=b.GetComponent<SettlementFacilityFocus>();f.Paths=paths.Select(p=>new SettlementFacilityFocus.Path{Points=p.Select(v=>v-new Vector2(x,y)).ToArray()}).ToArray();f.ContourMaterial=mat;f.Help=help;f.FacilityName=name;f.Caption.SetActive(false);f.Focus.SetActive(false);}
 public static string Run(){const string path="Assets/Prefabs/Settlement/SettlementScreen.prefab";const string mp="Assets/Settings/SettlementFacilityContour.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!mat){mat=new Material(Shader.Find("Demo5/SettlementFacilityContour"));AssetDatabase.CreateAsset(mat,mp);}var root=PrefabUtility.LoadPrefabContents(path);try{var c=root.GetComponent<SettlementController>();var old=c.Main.transform.Find("FacilityHelp");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var help=UnityEngine.Object.Instantiate(c.NoticeBody,c.Main.transform);help.name="FacilityHelp";var r=help.rectTransform;r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(32,-746);r.sizeDelta=new Vector2(552,38);help.fontSize=22;help.alignment=TextAnchor.MiddleLeft;help.color=new Color(.9f,.86f,.75f);help.text="시설 위에 마우스 · Alt: 모든 시설 강조";help.gameObject.SetActive(true);
 c.Bed.GetComponent<SettlementFacilityFocus>().Help=help; if(!c.Bed.GetComponent<SettlementFacilityFocus>().SilhouetteMask) Set(c.Bed,mat,help,"잠자리",Points(414,293,487,293,513,304,502,347,489,408,485,434,362,445,356,425,360,388,386,337),Points(553,297,639,293,664,306,674,367,666,432,540,444,532,427,536,394));
 Set(c.Stock,mat,help,"식수 · 조리",Points(829,322,839,321,843,334,854,344,854,387,848,395,815,394,812,385,816,343,825,333),Points(863,314,873,314,875,330,886,340,887,387,880,393,858,391,857,341,864,330),Points(904,326,968,319,1002,331,1007,400,979,410,906,405));
 Set(c.Workbench,mat,help,"작업대",Points(1118,310,1139,308,1141,280,1205,277,1240,292,1241,313,1361,311,1386,338,1377,426,1362,444,1351,354,1170,352,1161,450,1147,449,1146,347,1117,337));
 Set(c.Cabinet,mat,help,"공용 창고",Points(750,725,855,725,841,756,837,793,730,807,730,767),Points(862,725,939,725,918,766,918,791,839,808,839,769));
 Set(c.Exit,mat,help,"외부 탐험",Points(1742,335,1869,334,1892,487,1874,526,1760,520,1744,497));
 Set(c.Development.ResearchButton,mat,help,"연구대",Points(1050,702,1224,702,1204,755,1024,755));
 PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/Settlement.unity");return "Furniture silhouette contours saved; world render order 5 behind survivors; polygon hit test and footer help.";}
}
